1	/**
2	 * The step machine behind the builder's progress display.
3	 *
4	 * ─────────────────────────────────────────────────────────────────────────────
5	 * WHY THIS IS A PURE REDUCER
6	 * ─────────────────────────────────────────────────────────────────────────────
7	 * `AIProgress` is only honest if every step change is caused by something that
8	 * actually happened. Keeping the mapping here — with no timers, no setTimeout
9	 * and no access to the clock — makes that structurally true rather than a
10	 * promise in a comment: this module CANNOT advance a step on its own, because
11	 * the only way to move it is to hand it a signal.
12	 *
13	 * The chat panel's step list, the initial-build overlay and the veil over the
14	 * preview all render from one `BuildRun`, so the three of them cannot disagree
15	 * about what is happening.
16	 *
17	 * This is deliberately the same shape as the reducer behind the create flow
18	 * (app/(portal)/dashboard/new/build-steps.ts). The two surfaces show a customer
19	 * the same product and must not narrate a build in two different vocabularies.
20	 * The step LABELS differ, because an edit is not a create and "Writing your
21	 * site's files" is the wrong sentence for someone who asked to change a button.
22	 *
23	 * ─────────────────────────────────────────────────────────────────────────────
24	 * THE REAL SSE VOCABULARY OF /api/generate  (audited against route.ts,
25	 * lib/agent.ts, lib/agent-sdk.ts and lib/build-narration.ts)
26	 * ─────────────────────────────────────────────────────────────────────────────
27	 * `app/api/generate/route.ts` writes `data: <json>\n\n` frames. Exactly six
28	 * event shapes ever reach the client:
29	 *
30	 *   { type: "text",     text }                 assistant prose deltas
31	 *   { type: "progress", text }                 one narrated tool call
32	 *   { type: "status",   text }                 a phase the server names itself
33	 *   { type: "file",     path, action }         a source file was written/deleted
34	 *   { type: "done",     credits, remaining, filesWritten, buildId,
35	 *                       repairAttempts, repairWaived, waivedCredits }
36	 *   { type: "error",    message }
37	 *
38	 * A seventh, { type: "usage", … }, is produced by the agent and consumed
39	 * SERVER-SIDE for billing. It is never forwarded, so the client cannot show a
40	 * live spend readout during a build and nothing here pretends it can. The
41	 * charge is known once, on `done`.
42	 *
43	 * The two text channels are not free-form. Their producers are enumerable:
44	 *
45	 *   `progress` — narrateTool() in lib/build-narration.ts, one line per real
46	 *     tool call, with consecutive duplicates collapsed by the route:
47	 *       "Writing <thing>" / "Writing a file"      (Write, write_file)
48	 *       "Updating <thing>" / "Making an edit"     (Edit)
49	 *       "Removing <thing>" / "Removing a file"    (delete_file)
50	 *       "Looking through the project"             (Read, Glob, Grep — sdk)
51	 *       "Running a command"                       (Bash — sdk)
52	 *     plus two emitted directly:
53	 *       "Picking out icons and artwork"           (lib/agent.ts, find_assets)
54	 *       "Compiling the site"                      (route, before buildSite();
55	 *                                                  bypasses the dedupe)
56	 *
57	 *   `status` — only two producers:
58	 *       "Building your site…" / "Applying your changes…"  (sdk engine, once)
59	 *       "Build didn't compile — fixing it…"               (route, per repair;
60	 *                                                          MAX_BUILD_ATTEMPTS
61	 *                                                          is 2, so at most one)
62	 *
63	 * ─────────────────────────────────────────────────────────────────────────────
64	 * WHAT THAT VOCABULARY CAN AND CANNOT SUPPORT
65	 * ─────────────────────────────────────────────────────────────────────────────
66	 * There is no "planning" marker and no "designing" marker, and nothing can
67	 * separate layout work from copy work — a write to src/components/Hero.tsx is
68	 * one `file` event whether the model was laying out a grid or writing the
69	 * headline. A longer list would mean inventing the extra entries, and a step
70	 * that lights up because four seconds elapsed is exactly the fake this exists
71	 * to remove. So: FOUR steps, each entered or completed by a specific
72	 * observable fact.
73	 *
74	 *   0 sending    done when POST /api/generate answers 200 with a body — which
75	 *                means the kill switch, the balance, the spend cap and the
76	 *                rate limit all passed and a Build row exists
77	 *   1 thinking   done at the first evidence of a WRITE (a `file` event, or a
78	 *                narrateTool line from the Write/Edit/delete branch)
79	 *   2 writing    done when the route sends progress "Compiling the site"
80	 *   3 compiling  done on `done`
81	 *
82	 * The list can move BACKWARD. `status: "Build didn't compile — fixing it…"`
83	 * returns the active step to `writing` and increments a real counter, because
84	 * that is what the server just did — the files are being changed again. An
85	 * `error` freezes the list and marks the step it died on as failed. A stream
86	 * that closes with neither `done` nor `error` is a dropped connection and is
87	 * never reported as a finish.
88	 */
89	
90	import { stepsAt, type ProgressStep } from "@/components/ui/AIProgress";
91	
92	/** The literal the route sends immediately before buildSite(). */
93	const COMPILING_LINE = "Compiling the site";
94	
95	/** The literal the route sends before a repair pass. Matched on the stable
96	    leading clause rather than the whole string, so trailing wording can change
97	    without silently breaking the mapping — and if it ever stops matching, the
98	    list simply shows one fewer true transition rather than a wrong one. */
99	const REPAIR_PREFIX = /^Build didn['’]t compile/;
100	
101	/** Every narrateTool branch that means a file was touched. "Making an edit" is
102	    the Edit branch when the tool call carried no readable path. */
103	const WRITE_LINE = /^(Writing|Updating|Removing|Making an edit)\b/;
104	
105	const STEP = { sending: 0, thinking: 1, writing: 2, compiling: 3 } as const;
106	
107	/** Wording per build kind. The create column is deliberately the same as the
108	    create flow's, so someone who started a site on /dashboard/new and then
109	    edits it here is not told the same work in two different voices. */
110	const LABELS: Record<"create" | "edit", { id: string; label: string }[]> = {
111	  create: [
112	    { id: "sending", label: "Sending your brief to Kodely" },
113	    { id: "thinking", label: "Reading the brief and the starter files" },
114	    { id: "writing", label: "Writing your site’s files" },
115	    { id: "compiling", label: "Compiling the site" },
116	  ],
117	  edit: [
118	    { id: "sending", label: "Sending your change" },
119	    { id: "thinking", label: "Reading your site and working out the change" },
120	    { id: "writing", label: "Editing the files" },
121	    { id: "compiling", label: "Compiling the site" },
122	  ],
123	};
124	
125	/** One frame off the wire, after narrowing. */
126	export type StreamEvent =
127	  | { type: "text"; text: string }
128	  | { type: "progress"; text: string }
129	  | { type: "status"; text: string }
130	  | { type: "file"; path: string; action: string }
131	  | {
132	      type: "done";
133	      credits: number;
134	      remaining: number;
135	      filesWritten: number;
136	      buildId: string | null;
137	      repairAttempts: number;
138	      repairWaived: boolean;
139	      waivedCredits: number;
140	    }
141	  | { type: "error"; message: string };
142	
143	function str(v: unknown, fallback = ""): string {
144	  return typeof v === "string" ? v : fallback;
145	}
146	function num(v: unknown, fallback = 0): number {
147	  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
148	}
149	
150	/**
151	 * Narrow one parsed SSE payload. Returns null for anything unrecognised — a
152	 * frame we cannot read must not move the step list, and must not throw and
153	 * kill a build that is otherwise going fine. The route adds fields to `done`
154	 * over time and explicitly expects the client to ignore what it does not know.
155	 */
156	export function parseStreamEvent(raw: unknown): StreamEvent | null {
157	  if (typeof raw !== "object" || raw === null) return null;
158	  const e = raw as Record<string, unknown>;
159	  switch (e.type) {
160	    case "text":
161	      return { type: "text", text: str(e.text) };
162	    case "progress":
163	      return { type: "progress", text: str(e.text) };
164	    case "status":
165	      return { type: "status", text: str(e.text) };
166	    case "file":
167	      return { type: "file", path: str(e.path), action: str(e.action) };
168	    case "done":
169	      return {
170	        type: "done",
171	        credits: num(e.credits),
172	        remaining: num(e.remaining),
173	        filesWritten: num(e.filesWritten),
174	        buildId: typeof e.buildId === "string" ? e.buildId : null,
175	        repairAttempts: num(e.repairAttempts),
176	        repairWaived: e.repairWaived === true,
177	        waivedCredits: num(e.waivedCredits),
178	      };
179	    case "error":
180	      return { type: "error", message: str(e.message, "The build failed.") };
181	    default:
182	      return null;
183	  }
184	}
185	
186	export type BuildOutcome = "running" | "succeeded" | "failed";
187	
188	export type BuildRun = {
189	  /** Fixed when the build starts. `isFirstBuild` flips the moment the user's
190	      message joins the list, so a running build must not relabel itself. */
191	  kind: "create" | "edit";
192	  index: number;
193	  outcome: BuildOutcome;
194	  /** The most recent progress/status line, VERBATIM. lib/build-narration.ts is
195	      the intended source of this text and is already written for a
196	      non-developer, so it is shown as-is and never paraphrased. */
197	  line: string | null;
198	  /** `file` events seen. On the sdk engine these can arrive in one batch after
199	      the build, so this is evidence a write happened — not a live count. */
200	  filesTouched: number;
201	  /** Repair passes the SERVER announced. Never inferred from a stall. */
202	  repairs: number;
203	  /**
204	   * The request was answered 200 with a readable body. That is the line
205	   * between "refused before anything happened" and "the server started work":
206	   * route.ts writes the Build row AND the user's Message row before it returns
207	   * the stream, so past this point a retry is a follow-up edit rather than a
208	   * clean re-run. Nothing else can tell those two apart.
209	   */
210	  accepted: boolean;
211	};
212	
213	export function startRun(kind: "create" | "edit"): BuildRun {
214	  return {
215	    kind,
216	    index: STEP.sending,
217	    outcome: "running",
218	    line: null,
219	    filesTouched: 0,
220	    repairs: 0,
221	    accepted: false,
222	  };
223	}
224	
225	export type BuildSignal =
226	  /** POST /api/generate answered 200 and handed back a readable body. */
227	  | { kind: "accepted" }
228	  /** One frame off the stream. */
229	  | { kind: "sse"; event: StreamEvent }
230	  /** The request was refused, the fetch threw, or the stream ended without a
231	      terminal event. The step list stops where it is, marked failed. */
232	  | { kind: "failed" };
233	
234	/** Pure. The ONLY way a BuildRun changes. */
235	export function reduceBuild(run: BuildRun, signal: BuildSignal): BuildRun {
236	  if (run.outcome !== "running") return run;
237	  switch (signal.kind) {
238	    case "accepted":
239	      return { ...run, accepted: true, index: Math.max(run.index, STEP.thinking) };
240	    case "failed":
241	      return { ...run, outcome: "failed" };
242	    case "sse":
243	      return applyEvent(run, signal.event);
244	  }
245	}
246	
247	function applyEvent(run: BuildRun, event: StreamEvent): BuildRun {
248	  switch (event.type) {
249	    // Prose from the model. Real evidence the request is being worked on, but
250	    // it names no phase, so it moves nothing.
251	    case "text":
252	      return run;
253	
254	    case "progress":
255	    case "status": {
256	      const text = event.text;
257	      const next = { ...run, line: text || run.line };
258	
259	      // The server just told us the previous attempt did not compile. Going
260	      // back to `writing` is not a glitch — the build genuinely went back.
261	      if (REPAIR_PREFIX.test(text)) {
262	        return { ...next, index: STEP.writing, repairs: next.repairs + 1 };
263	      }
264	      if (text === COMPILING_LINE) return { ...next, index: STEP.compiling };
265	      if (WRITE_LINE.test(text)) return { ...next, index: Math.max(next.index, STEP.writing) };
266	      // "Looking through the project", "Running a command", "Picking out icons
267	      // and artwork", "Applying your changes…" — all real, none of them a
268	      // phase change. They show up in the live line and nowhere else.
269	      return { ...next, index: Math.max(next.index, STEP.thinking) };
270	    }
271	
272	    case "file":
273	      return {
274	        ...run,
275	        filesTouched: run.filesTouched + 1,
276	        index: Math.max(run.index, STEP.writing),
277	      };
278	
279	    case "done":
280	      return {
281	        ...run,
282	        outcome: "succeeded",
283	        index: LABELS[run.kind].length,
284	        line: null,
285	        // The server's own counts are authoritative over the events we
286	        // happened to see — a dropped frame must not understate the work.
287	        filesTouched: Math.max(run.filesTouched, event.filesWritten),
288	        repairs: Math.max(run.repairs, event.repairAttempts),
289	      };
290	
291	    case "error":
292	      return { ...run, outcome: "failed" };
293	  }
294	}
295	
296	/**
297	 * The step list, ready for `AIProgress`.
298	 *
299	 * `live` swaps the active step's generic label for the real narration line
300	 * when there is one, so "Editing the files" becomes "Writing the hero section"
301	 * — the actual tool call, not a guess about it.
302	 */
303	export function buildSteps(run: BuildRun, { live = true }: { live?: boolean } = {}): ProgressStep[] {
304	  const labels = LABELS[run.kind];
305	  if (run.outcome === "succeeded") return stepsAt(labels, labels.length);
306	  const active = Math.min(run.index, labels.length - 1);
307	  if (run.outcome === "failed") return stepsAt(labels, active, true);
308	  const shown =
309	    live && run.line
310	      ? labels.map((l, i) => (i === active ? { ...l, label: run.line as string } : l))
311	      : labels;
312	  return stepsAt(shown, active);
313	}
314	
315	/** One sentence for the places too small for the whole list — the veil's
316	    caption and the browser tab title. Always the truest thing we have. */
317	export function buildHeadline(run: BuildRun): string {
318	  if (run.outcome === "succeeded") return "Change applied";
319	  if (run.outcome === "failed") return "Build failed";
320	  if (run.line) return run.line;
321	  return buildSteps(run, { live: false }).find((s) => s.state === "active")?.label ?? "Working";
322	}
