673	/* ══════════════════════════════════════════════════════════════════════════
674	   PRODUCT UTILITIES
675	   Small, named, reused everywhere in the portal and builder. Each one exists
676	   because expressing it as a Tailwind class chain at every call site is how
677	   the old portal drifted out of alignment with itself.
678	   ══════════════════════════════════════════════════════════════════════════ */
679	
680	/* One focus treatment for the whole product. Always visible, never removed —
681	   a ring that only shows on :focus-visible still has to exist. */
682	.k-focus:focus-visible {
683	  outline: 2px solid var(--brand-ring);
684	  outline-offset: 2px;
685	}
686	
687	/* Type scale. Display sizes get negative tracking (optical correction — at
688	   32px+ the default spacing reads loose); the label size gets positive
689	   tracking and uppercase, which is the only place caps are used. */
690	.k-display {
691	  font-size: clamp(1.75rem, 1.2rem + 1.6vw, 2.35rem);
692	  line-height: 1.1;
693	  letter-spacing: -0.028em;
694	  font-weight: 600;
695	  text-wrap: balance;
696	}
697	.k-h1 {
698	  font-size: 1.5rem;
699	  line-height: 1.2;
700	  letter-spacing: -0.02em;
701	  font-weight: 600;
702	}
703	.k-h2 {
704	  font-size: 1.0625rem;
705	  line-height: 1.35;
706	  letter-spacing: -0.011em;
707	  font-weight: 600;
708	}
709	.k-label {
710	  font-size: 0.6875rem;
711	  line-height: 1;
712	  letter-spacing: 0.07em;
713	  text-transform: uppercase;
714	  font-weight: 600;
715	  color: var(--text-3);
716	}
717	/* Anywhere digits stack in a column — usage, credits, invoices, versions. */
718	.k-num {
719	  font-variant-numeric: tabular-nums;
720	  font-feature-settings: "tnum" 1;
721	}
722	
723	/* Any wide child (table, code, diagram) scrolls inside its own box so the
724	   page body never scrolls sideways. */
725	.k-scroll-x {
726	  overflow-x: auto;
727	  overscroll-behavior-x: contain;
728	}
729	
730	/* A 1px brand-gradient hairline around a panel, done with a padding box so it
731	   works on any background without a second opaque layer to keep in sync. */
732	.k-gradient-border {
733	  background:
734	    linear-gradient(var(--surface), var(--surface)) padding-box,
735	    var(--brand-gradient) border-box;
736	  border: 1px solid transparent;
737	}
738	
739	/* ── AI progress: the three states a step can be in ──
740	   Reused by the build overlay, the chat progress list and the preview
741	   loading treatment, so all three read as the same object. */
742	@keyframes k-step-pulse {
743	  0%,
744	  100% {
745	    opacity: 0.45;
746	    transform: scale(0.88);
747	  }
748	  50% {
749	    opacity: 1;
750	    transform: scale(1);
751	  }
752	}
753	.k-step-active {
754	  animation: k-step-pulse 1.4s var(--ease-io) infinite;
755	}
756	
757	@keyframes k-step-in {
758	  from {
759	    opacity: 0;
760	    transform: translateY(4px);
761	  }
762	  to {
763	    opacity: 1;
764	    transform: translateY(0);
765	  }
766	}
767	.k-step-in {
768	  animation: k-step-in 0.32s var(--ease) both;
769	}
770	
771	/* The travelling sheen along an in-progress bar. Position, not a moving
772	   child, so there is nothing to clip. */
773	@keyframes k-indeterminate {
774	  from {
775	    background-position: 200% 0;
776	  }
777	  to {
778	    background-position: -200% 0;
779	  }
780	}
781	.k-indeterminate {
782	  background-image: linear-gradient(
783	    90deg,
784	    var(--brand-tint) 0%,
785	    var(--brand) 40%,
786	    var(--brand) 60%,
787	    var(--brand-tint) 100%
788	  );
789	  background-size: 200% 100%;
790	  animation: k-indeterminate 1.6s linear infinite;
791	}
