37	/** Only rendered after a click (the panel is never the first view), so a
38	    relative time cannot cause a hydration mismatch. */
39	function ago(iso: string): string {
40	  const ms = Date.now() - new Date(iso).getTime();
41	  const mins = Math.round(ms / 60000);
42	  if (mins < 1) return "just now";
43	  if (mins < 60) return `${mins} min ago`;
44	  const hours = Math.round(mins / 60);
45	  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`;
46	  const days = Math.round(hours / 24);
47	  return `${days} day${days === 1 ? "" : "s"} ago`;
48	}
