9	// The prompt box and everything that belongs to the act of asking for a change.
10	//
11	// EVERY CONTROL HERE IS REAL. What was considered and left out, and why:
12	//
13	//  * Attaching a non-image file. There is no multipart handler, no object
14	//    store and no path by which a .pdf or a .zip could reach the model —
15	//    app/api/generate/route.ts reads a JSON body and accepts exactly one
16	//    optional field, `image`, matched against
17	//    /^data:(image\/(?:png|jpeg|webp));base64,(.+)$/ and silently dropped
18	//    otherwise. So the picker accepts images only and says so.
19	//  * A voice button. Nothing transcribes.
20	//  * "Save as draft" / "queue this change". The route runs one build per
21	//    request, synchronously, over an open stream. There is no queue.
22	//
23	// Stop IS real and is not a UI trick: aborting the fetch closes the response
24	// body, which fires cancel() on the route's ReadableStream, which aborts the
25	// in-flight model request server-side. The build row is then written FAILED
26	// with creditsCharged: 0. See the comment block in BuildInterrupted.tsx.
27	
28	// Downscale + re-encode client-side, the same treatment the homepage prompt
29	// gives a reference image: a phone photo is several megabytes of JSON body and
30	// a large number of vision tokens, and a reference only needs to be legible.
31	// toDataURL("image/jpeg") produces exactly the `data:image/jpeg;base64,` shape
32	// the route's regex accepts.
33	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
34	  const bitmap = await createImageBitmap(file);
35	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
36	  const canvas = document.createElement("canvas");
37	  canvas.width = Math.round(bitmap.width * scale);
38	  canvas.height = Math.round(bitmap.height * scale);
39	  const ctx = canvas.getContext("2d");
40	  if (!ctx) throw new Error("This browser can’t resize the image.");
41	  ctx.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
42	  return canvas.toDataURL("image/jpeg", quality);
43	}
