30	  // cascading-render pattern React lints against, and it also meant three
31	  // setState calls could disagree for a render.
32	  //
33	  // Comparing the nonce the effect last ANSWERED against the nonce it was last
34	  // ASKED gives the same answer with no reset and no extra render pass. Loading
35	  // deliberately keeps the previous document on screen: a Reload that blanks
36	  // the page and then repaints it reads as the site having broken.
37	  const [result, setResult] = useState<{ nonce: number; doc: string | null; error: string | null }>(
38	    { nonce: -1, doc: null, error: null },
39	  );
40	  const loading = result.nonce !== nonce;
41	  const doc = result.doc;
42	  // A stale error from the previous attempt must not sit on screen while the
43	  // next one is still in flight.
44	  const error = loading ? null : result.error;
45	
46	  useEffect(() => {
47	    const controller = new AbortController();
48	    const base = `/api/preview/${projectId}`;
49	
50	    (async () => {
51	      try {
52	        const res = await fetch(`${base}/index.html`, {
53	          signal: controller.signal,
54	          cache: "no-store",
55	        });
56	        if (!res.ok) throw new Error("The preview could not be loaded.");
57	        // `missing` is dropped here on purpose. The editor reports it because
58	        // it is where you would act on it; this tab is for looking at the
59	        // page, and a warning strip over someone's site is not what they
60	        // opened a clean tab for.
61	        const built = await buildPreviewDocument(await res.text(), async (path) => {
62	          const asset = await fetch(`${base}/${path}`, {
63	            signal: controller.signal,
64	            cache: "no-store",
65	          });
66	          return asset.ok ? await asset.text() : null;
67	        });
68	        if (controller.signal.aborted) return;
69	        setResult({ nonce, doc: built.doc, error: null });
70	      } catch (err) {
71	        if (controller.signal.aborted) return;
72	        setResult({
73	          nonce,
74	          doc: null,
75	          error: err instanceof Error ? err.message : "The preview could not be loaded.",
76	        });
77	      }
78	      // No `finally`: an aborted request must NOT record an answer for this
79	      // nonce, or a superseded fetch would mark the newer request as finished.
80	    })();
81	
82	    return () => controller.abort();
83	  }, [projectId, nonce]);
84	
85	  return (
86	    <div className="flex h-dvh flex-col bg-canvas">
87	      <div className="flex shrink-0 flex-wrap items-center gap-2 border-b border-hair bg-surface px-3 py-2">
88	        <Badge tone="neutral" dot>
89	          Draft preview
90	        </Badge>
91	        <span className="min-w-0 flex-1 truncate text-[0.8125rem] text-ink-2">{projectName}</span>
92	        <Button size="xs" variant="ghost" className="border border-hair" onClick={() => setNonce((n) => n + 1)}>
93	          Reload
94	        </Button>
95	        <ButtonLink size="xs" href={`/projects/${projectId}`}>
96	          Back to the editor
97	        </ButtonLink>
98	      </div>
99	
100	      <div className="min-h-0 flex-1 bg-inset">
101	        {error ? (
102	          <div className="grid h-full place-items-center p-6">
103	            <EmptyState
104	              kind="unavailable"
105	              title="Nothing to preview"
106	              body={error}
107	              action={
108	                <ButtonLink size="sm" href={`/projects/${projectId}`}>
109	                  Back to the editor
110	                </ButtonLink>
111	              }
112	            />
113	          </div>
114	        ) : doc === null ? (
115	          <div className="flex h-full items-center justify-center gap-2 text-sm text-ink-3">
116	            {loading && <Spinner size={16} />}
117	            {loading ? "Assembling the preview…" : "Nothing built yet."}
118	          </div>
119	        ) : (
120	          <iframe
121	            key={nonce}
122	            srcDoc={doc}
123	            sandbox="allow-scripts allow-forms"
124	            title={`Draft preview of ${projectName}`}
125	            className="h-full w-full border-0 bg-white"
126	          />
127	        )}
128	      </div>
129	    </div>
130	  );
131	}
