3	import { useEffect, useMemo, useRef, useState } from "react";
4	
5	// Cmd/Ctrl-K palette over the actions the editor already has. It invents no
6	// new capability — every entry is a button that exists somewhere in the
7	// header or the sidebar. The value is that the fastest path to any of them
8	// stops depending on knowing where it lives.
9	//
10	// Keyboard contract (this is the whole point of the feature, so it is
11	// deliberately explicit rather than left to the browser):
12	//  - focus moves into the filter input on open, and back to whatever had it
13	//    on close — synchronously, so a command that focuses something itself
14	//    (Focus prompt box) still wins the race.
15	//  - Tab is trapped inside the dialog; Escape closes it.
16	//  - Arrow keys move a virtual selection; the input keeps real focus and
17	//    aria-activedescendant points at the highlighted row, which is the
18	//    combobox pattern screen readers already understand.
19	//
20	// The component mounts only while open, so there is no open/closed state to
21	// reset — and the selection is stored as a command ID and resolved to an
22	// index during render, so a list that re-filters under the user cannot leave
23	// a stale index pointing at the wrong row.
24	
25	export type Command = {
26	  id: string;
27	  label: string;
28	  /** Extra words that should match the filter but need not be shown. */
29	  keywords?: string;
30	  /** Right-aligned hint — a real key combination, or a state note. */
31	  hint?: string;
32	  disabled?: boolean;
33	  /** Why it is unavailable. Shown in place of the hint on a dimmed row. */
34	  disabledReason?: string;
35	  run: () => void;
36	};
37	
38	export type CommandGroup = { heading: string; commands: Command[] };
39	
40	const FOCUS_RING =
41	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
42	
43	function matches(cmd: Command, query: string): boolean {
44	  if (!query) return true;
45	  const haystack = `${cmd.label} ${cmd.keywords ?? ""}`.toLowerCase();
46	  // Every whitespace-separated term must appear somewhere — "pub site" finds
47	  // "Publish site" without needing the words adjacent.
48	  return query
49	    .toLowerCase()
50	    .split(/\s+/)
51	    .filter(Boolean)
52	    .every((term) => haystack.includes(term));
53	}
54	
55	export default function CommandPalette({
56	  onClose,
57	  groups,
58	}: {
59	  /** Closes the palette. Restoring focus is the caller's job, because the
60	      caller is the only one that knows what had focus before it opened —
61	      and it must happen before `run`, so a command that moves focus wins. */
62	  onClose: (run?: () => void) => void;
63	  groups: CommandGroup[];
64	}) {
65	  const [query, setQuery] = useState("");
66	  const [selectedId, setSelectedId] = useState<string | null>(null);
67	  const dialogRef = useRef<HTMLDivElement>(null);
68	  const listRef = useRef<HTMLDivElement>(null);
69	  const inputRef = useRef<HTMLInputElement>(null);
70	
71	  // Flattened, filtered, still carrying the heading each row sits under so the
72	  // list can render groups without a second pass over the source data.
73	  const rows = useMemo(() => {
74	    const out: { heading: string | null; cmd: Command }[] = [];
75	    for (const group of groups) {
76	      const hits = group.commands.filter((c) => matches(c, query));
77	      hits.forEach((cmd, i) => out.push({ heading: i === 0 ? group.heading : null, cmd }));
78	    }
79	    return out;
80	  }, [groups, query]);
81	
82	  // Derived, never stored: if the highlighted command filtered itself out (or
83	  // just became unavailable), the highlight falls to the first row that can
84	  // actually run, so Enter is never a no-op.
85	  const firstEnabled = rows.findIndex((r) => !r.cmd.disabled);
86	  const held = rows.findIndex((r) => r.cmd.id === selectedId && !r.cmd.disabled);
87	  const selected = held >= 0 ? held : firstEnabled;
88	
89	  function highlight(index: number) {
90	    setSelectedId(rows[index]?.cmd.id ?? null);
91	    listRef.current?.querySelector(`[data-index="${index}"]`)?.scrollIntoView({ block: "nearest" });
92	  }
93	
94	  function move(delta: number) {
95	    if (rows.length === 0) return;
96	    const start = selected < 0 ? (delta > 0 ? -1 : rows.length) : selected;
97	    for (let step = 1; step <= rows.length; step++) {
98	      const next = (start + delta * step + rows.length * step) % rows.length;
99	      if (!rows[next].cmd.disabled) {
100	        highlight(next);
101	        return;
102	      }
103	    }
104	  }
105	
106	  function onKeyDown(e: React.KeyboardEvent) {
107	    // The same chord that opened it closes it, and closes it the proper way —
108	    // through onClose, so focus goes back where it came from.
109	    if ((e.metaKey || e.ctrlKey) && !e.altKey && e.key.toLowerCase() === "k") {
110	      e.preventDefault();
111	      e.stopPropagation();
112	      onClose();
113	      return;
114	    }
115	    if (e.key === "Escape") {
116	      e.preventDefault();
117	      e.stopPropagation();
118	      onClose();
119	      return;
120	    }
121	    if (e.key === "Tab") {
122	      // Only the input and the close button are tabbable, so cycling between
123	      // them is the entire trap — focus can never reach the page behind.
124	      const focusable = dialogRef.current?.querySelectorAll<HTMLElement>(
125	        'input, button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])',
126	      );
127	      if (!focusable || focusable.length === 0) return;
128	      const first = focusable[0];
129	      const last = focusable[focusable.length - 1];
130	      if (e.shiftKey && document.activeElement === first) {
131	        e.preventDefault();
132	        last.focus();
133	      } else if (!e.shiftKey && document.activeElement === last) {
134	        e.preventDefault();
135	        first.focus();
136	      }
137	      return;
138	    }
139	    if (e.key === "ArrowDown") {
140	      e.preventDefault();
141	      move(1);
142	    } else if (e.key === "ArrowUp") {
143	      e.preventDefault();
144	      move(-1);
145	    } else if (e.key === "Home") {
146	      e.preventDefault();
147	      highlight(firstEnabled);
148	    } else if (e.key === "End") {
149	      e.preventDefault();
150	      for (let i = rows.length - 1; i >= 0; i--) {
151	        if (!rows[i].cmd.disabled) {
152	          highlight(i);
153	          break;
154	        }
155	      }
156	    } else if (e.key === "Enter") {
157	      e.preventDefault();
158	      const row = rows[selected];
159	      if (row && !row.cmd.disabled) onClose(row.cmd.run);
160	    }
161	  }
162	
163	  // Last-resort Escape. Everything above binds the keyboard to the dialog
164	  // subtree, and the editor unbinds its own global shortcuts while the palette
165	  // is open — so IF focus ever ends up outside the dialog, Escape has nobody
166	  // listening at all and the modal cannot be dismissed from the keyboard.
167	  // That was verified in the browser by moving focus out and pressing Escape:
168	  // before this listener the palette stayed open, after it the palette closes.
169	  // An undismissable modal is a bad enough failure to be worth the second
170	  // lock even though the mousedown pin below should prevent getting there.
171	  // This fires only when the dialog's own handler didn't: that one calls
172	  // stopPropagation, which stops the native event before it reaches window —
173	  // also verified, by checking Escape from inside still closes exactly once.
174	  useEffect(() => {
175	    const onEscape = (e: KeyboardEvent) => {
176	      if (e.key === "Escape") {
177	        e.preventDefault();
178	        onClose();
179	      }
180	    };
181	    window.addEventListener("keydown", onEscape);
182	    return () => window.removeEventListener("keydown", onEscape);
183	  }, [onClose]);
184	
185	  const activeId = selected >= 0 && rows[selected] ? `kodely-cmd-${rows[selected].cmd.id}` : undefined;
186	
187	  return (
188	    <div
189	      className="fixed inset-0 z-50 flex items-start justify-center bg-black/40 p-4 pt-[12vh]"
190	      onMouseDown={(e) => {
191	        if (e.target === e.currentTarget) onClose();
192	      }}
193	    >
194	      <div
195	        ref={dialogRef}
196	        role="dialog"
197	        aria-modal="true"
198	        aria-labelledby="kodely-cmd-title"
199	        onKeyDown={onKeyDown}
200	        // Keydown is handled here, on the dialog, so it only ever arrives if
201	        // focus is INSIDE the dialog. That makes "the input keeps focus" load
202	        // bearing rather than cosmetic, and it is also precisely what the
203	        // combobox pattern requires: aria-activedescendant only means anything
204	        // while the input itself holds real focus.
205	        //
206	        // So any mousedown not aimed at the input has its default — the focus
207	        // change — cancelled. Click still fires: rows still run, the Esc
208	        // button still closes; the caret simply never leaves the filter box.
209	        //
210	        // Measured, so as not to overclaim: Chrome here did NOT blur the
211	        // previously focused element when a plain non-focusable div was
212	        // clicked, so this is not repairing an observed break in that browser.
213	        // Where exactly focus lands after clicking non-focusable chrome is a
214	        // long-standing point of difference between engines, and the failure
215	        // it would cause here is severe and silent (Escape stops closing, Tab
216	        // leaves the overlay). Pinning focus makes the outcome the same
217	        // everywhere instead of depending on that. The window-level Escape
218	        // listener above is the second, independent lock.
219	        onMouseDown={(e) => {
220	          if (e.target !== inputRef.current) e.preventDefault();
221	        }}
222	        className="flex w-full max-w-lg flex-col overflow-hidden rounded-xl border border-black/10 bg-white shadow-xl dark:border-white/10 dark:bg-neutral-900"
223	      >
224	        <h2 id="kodely-cmd-title" className="sr-only">
225	          Command palette
226	        </h2>
227	
228	        <div className="flex items-center gap-2 border-b border-black/10 px-3 py-2.5 dark:border-white/10">
229	          <label htmlFor="kodely-cmd-input" className="sr-only">
230	            Search commands
231	          </label>
232	          <input
233	            id="kodely-cmd-input"
234	            ref={inputRef}
235	            // Mounted only while open, so this is the whole of "focus the
236	            // input when the palette opens" — no effect required.
237	            autoFocus
238	            value={query}
239	            onChange={(e) => setQuery(e.target.value)}
240	            placeholder="Type a command…"
241	            autoComplete="off"
242	            spellCheck={false}
243	            role="combobox"
244	            aria-expanded="true"
245	            aria-controls="kodely-cmd-list"
246	            aria-activedescendant={activeId}
247	            aria-describedby="kodely-cmd-help"
248	            className={`min-w-0 flex-1 rounded-md bg-transparent px-1 py-0.5 text-sm outline-none placeholder:text-black/35 dark:placeholder:text-white/35 ${FOCUS_RING}`}
249	          />
250	          <button
251	            type="button"
252	            onClick={() => onClose()}
253	            aria-label="Close command palette"
254	            className={`shrink-0 rounded-md border border-black/15 px-2 py-0.5 text-xs text-black/60 hover:text-black dark:border-white/15 dark:text-white/60 dark:hover:text-white ${FOCUS_RING}`}
255	          >
256	            Esc
257	          </button>
258	        </div>
259	
260	        <div
261	          id="kodely-cmd-list"
262	          ref={listRef}
263	          role="listbox"
264	          aria-label="Commands"
265	          className="max-h-80 overflow-y-auto p-1.5"
266	        >
267	          {rows.length === 0 ? (
268	            <p className="px-2 py-6 text-center text-sm text-black/45 dark:text-white/45">
269	              No command matches “{query}”.
270	            </p>
271	          ) : (
272	            rows.map((row, i) => (
273	              <div key={row.cmd.id}>
274	                {row.heading && (
275	                  <div
276	                    role="presentation"
277	                    className="px-2 pb-1 pt-2 text-[11px] font-medium uppercase tracking-wide text-black/35 dark:text-white/35"
278	                  >
279	                    {row.heading}
280	                  </div>
281	                )}
282	                <div
283	                  id={`kodely-cmd-${row.cmd.id}`}
284	                  data-index={i}
285	                  role="option"
286	                  aria-selected={i === selected}
287	                  aria-disabled={row.cmd.disabled || undefined}
288	                  onMouseMove={() => {
289	                    if (!row.cmd.disabled && selected !== i) setSelectedId(row.cmd.id);
290	                  }}
291	                  onClick={() => {
292	                    if (!row.cmd.disabled) onClose(row.cmd.run);
293	                  }}
294	                  className={`flex cursor-default items-center justify-between gap-3 rounded-md px-2 py-1.5 text-sm ${
295	                    row.cmd.disabled
296	                      ? "text-black/30 dark:text-white/30"
297	                      : i === selected
298	                        ? "bg-black/10 dark:bg-white/10"
299	                        : "text-black/70 dark:text-white/70"
300	                  }`}
301	                >
302	                  <span className="min-w-0 truncate">{row.cmd.label}</span>
303	                  <span className="shrink-0 text-xs text-black/40 dark:text-white/40">
304	                    {row.cmd.disabled ? row.cmd.disabledReason : row.cmd.hint}
305	                  </span>
306	                </div>
307	              </div>
308	            ))
309	          )}
310	        </div>
311	
312	        <p
313	          id="kodely-cmd-help"
314	          className="border-t border-black/10 px-3 py-2 text-xs text-black/40 dark:border-white/10 dark:text-white/40"
315	        >
316	          ↑↓ to move · Enter to run · Esc to close
317	        </p>
318	      </div>
319	    </div>
320	  );
321	}
