1	import { redirect } from "next/navigation";
2	import { getCurrentUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import StandalonePreview from "./StandalonePreview";
5	
6	export const dynamic = "force-dynamic";
7	
8	// "Open in a new tab", for a DRAFT.
9	//
10	// This route exists because the obvious target does not work. /api/preview/<id>
11	// /index.html renders fine inside the editor's iframe only because the editor
12	// fetches its assets itself and inlines them (see preview-agent.ts). Opened as
13	// a top-level tab it would ask the browser to load the <script src="/assets/…">
14	// that Vite emitted — an absolute path, resolved against the APP origin, where
15	// there is no /assets route. The page would load and then render nothing.
16	//
17	// A blob: URL of the assembled document was considered and rejected outright: a
18	// blob inherits the creating page's origin, which would put generated customer
19	// JavaScript on the app's own origin with access to same-origin fetches. The
20	// whole reason the editor's iframe omits `allow-same-origin` is to prevent
21	// exactly that. A data: URL is a non-starter too — top-level navigation to
22	// data: is blocked in every current browser.
23	//
24	// So: a real page, owner-only like the API it reads, that assembles the same
25	// self-contained document and hands it to the same kind of sandboxed frame.
26	// The published site needs none of this and is linked to directly.
27	export default async function ProjectPreviewPage({
28	  params,
29	}: {
30	  params: Promise<{ id: string }>;
31	}) {
32	  const user = await getCurrentUser();
33	  if (!user) redirect("/login");
34	  const { id } = await params;
35	
36	  const project = await db.project.findFirst({
37	    where: { id, userId: user.id },
38	    select: { id: true, name: true },
39	  });
40	  if (!project) redirect("/dashboard");
41	
42	  return <StandalonePreview projectId={project.id} projectName={project.name} />;
43	}
