3	import { useEffect, useMemo, useRef, useState } from "react";
4	
5	// Search & social metadata, visible and editable WITHOUT paying for a build.
6	//
7	// Where these values actually live: there is no seo column anywhere. The head
8	// of the project's own `index.html` IS the storage (see lib/foundation.ts for
9	// the scaffold the agent is handed, and the head-writing instructions in the
10	// SYSTEM prompt in lib/agent.ts). So this panel reads the draft SOURCE
11	// index.html the editor already holds, and a save has to rewrite that same
12	// file — which is why the endpoint contract below is what it is.
13	//
14	// Three separate copies of index.html exist per project, and they are NOT
15	// interchangeable:
16	//   draft  + kind "source"  — what the agent edits and what this panel reads.
17	//   draft  + kind "build"   — the compiled output the in-editor preview serves.
18	//   published + kind "build" — what visitors get; only the publish route writes it.
19	// A save must touch the first two and must never touch the third: going live
20	// stays an explicit act. That is stated again on the endpoint contract below.
21	//
22	// What lib/site-seo.ts does on top of this, at serve time and for published
23	// sites only, is a BACKSTOP for gaps — it never overrides a value that is
24	// present. The "What visitors see" column mirrors those rules exactly so the
25	// panel can never show something different from what is actually served.
26	
27	/** lib/site-seo.ts's own placeholder constant. Not exported there; mirrored. */
28	const PLACEHOLDER_TITLE = "Kodely Site";
29	
30	// Guidance, not limits. Straight out of the SYSTEM prompt the builder is given
31	// (lib/agent.ts): title under ~60 characters, description ~150. Going over is
32	// allowed — search engines truncate, they do not reject — so this only ever
33	// changes a colour and a number, never disables the save.
34	const TITLE_TARGET = 60;
35	const DESC_TARGET = 150;
36	
37	const FOCUS_RING =
38	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
39	
40	const FIELD =
41	  "w-full rounded-lg border border-black/15 bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40";
42	
43	export type SeoTags = {
44	  title: string;
45	  description: string;
46	  ogTitle: string;
47	  ogDescription: string;
48	  /** Read-only here: it is an asset reference, not copy. */
49	  ogImage: string;
50	};
51	
52	const EMPTY: SeoTags = { title: "", description: "", ogTitle: "", ogDescription: "", ogImage: "" };
53	
54	/**
55	 * Read the head with the browser's own HTML parser rather than regexes:
56	 * attribute order, quoting style and entities (&amp;, &#39;) are all things
57	 * the builder writes freely and all things a regex would show back to the
58	 * user raw. This runs client-side only — the panel is never server-rendered,
59	 * since it mounts only once the user switches to this view.
60	 */
61	function parseHead(html: string | undefined): SeoTags {
62	  if (!html || typeof DOMParser === "undefined") return EMPTY;
63	  const doc = new DOMParser().parseFromString(html, "text/html");
64	  const content = (selector: string) =>
65	    doc.querySelector(selector)?.getAttribute("content")?.trim() ?? "";
66	  return {
67	    title: doc.querySelector("title")?.textContent?.trim() ?? "",
68	    description: content('meta[name="description"]'),
69	    ogTitle: content('meta[property="og:title"]'),
70	    ogDescription: content('meta[property="og:description"]'),
71	    ogImage: content('meta[property="og:image"]'),
72	  };
73	}
74	
75	/**
76	 * What a visitor and a crawler actually get for a PUBLISHED site, gaps
77	 * included. Mirrors applySeo() in lib/site-seo.ts line for line.
78	 *
79	 * One rule here is easy to get wrong and is deliberately preserved: an empty
80	 * og:description does NOT inherit the page description. applySeo computes one
81	 * generic string from the title and uses it for both, so leaving og:description
82	 * blank while writing a real description gets you the generic line in every
83	 * link preview. Showing that plainly is the point of this column.
84	 */
85	function servedValues(tags: SeoTags, projectName: string) {
86	  const title =
87	    !tags.title || tags.title === PLACEHOLDER_TITLE ? projectName : tags.title;
88	  const generated = `${title} — built with Kodely.`;
89	  return {
90	    title,
91	    titleIsFallback: !tags.title || tags.title === PLACEHOLDER_TITLE,
92	    description: tags.description || generated,
93	    descriptionIsFallback: !tags.description,
94	    ogTitle: tags.ogTitle || title,
95	    ogTitleIsFallback: !tags.ogTitle,
96	    ogDescription: tags.ogDescription || generated,
97	    ogDescriptionIsFallback: !tags.ogDescription,
98	  };
99	}
100	
101	function sameTags(a: SeoTags, b: SeoTags): boolean {
102	  return (
103	    a.title === b.title &&
104	    a.description === b.description &&
105	    a.ogTitle === b.ogTitle &&
106	    a.ogDescription === b.ogDescription
107	  );
108	}
109	
110	export default function SeoPanel({
111	  projectId,
112	  projectName,
113	  published,
114	  liveUrl,
115	  html,
116	  onSaved,
117	}: {
118	  projectId: string;
119	  projectName: string;
120	  published: boolean;
121	  /** Public URL, when the site is live. Used for the canonical/og:url note. */
122	  liveUrl: string | null;
123	  /** Draft source index.html, straight from the editor's file map. */
124	  html: string | undefined;
125	  /** Re-read the project's files after a successful save. */
126	  onSaved: () => void | Promise<void>;
127	}) {
128	  // ── The endpoint this panel needs ───────────────────────────────────────
129	  // PUT /api/projects/<id>/seo does not exist yet, and creating routes was
130	  // out of scope for this change. Rather than ship a Save button that is
131	  // quietly guaranteed to fail, the panel asks the server once whether the
132	  // route is there and says so plainly if it isn't. When the route ships,
133	  // nothing here needs to change.
134	  const endpoint = `/api/projects/${projectId}/seo`;
135	  const [saveSupport, setSaveSupport] = useState<"checking" | "ready" | "missing">("checking");
136	  const [saving, setSaving] = useState(false);
137	  const [saveError, setSaveError] = useState<string | null>(null);
138	  const [savedAt, setSavedAt] = useState<number | null>(null);
139	
140	  const current = useMemo(() => parseHead(html), [html]);
141	  const [draft, setDraft] = useState<SeoTags>(current);
142	  const baseline = useRef(current);
143	
144	  // Adopt new file contents (a finished build, or our own save landing) only
145	  // when the user has nothing unsaved in the boxes. Silently replacing text
146	  // someone is halfway through typing is worse than showing a stale value.
147	  useEffect(() => {
148	    setDraft((d) => (sameTags(d, baseline.current) ? current : d));
149	    baseline.current = current;
150	  }, [current]);
151	
152	  useEffect(() => {
153	    let cancelled = false;
154	    // OPTIONS: no side effects either way, and Next answers 405 for a route
155	    // that exists without this method versus 404 for no route at all.
156	    fetch(endpoint, { method: "OPTIONS" })
157	      .then((res) => {
158	        if (!cancelled) setSaveSupport(res.status === 404 ? "missing" : "ready");
159	      })
160	      .catch(() => {
161	        if (!cancelled) setSaveSupport("missing");
162	      });
163	    return () => {
164	      cancelled = true;
165	    };
166	  }, [endpoint]);
167	
168	  const dirty = !sameTags(draft, current);
169	  const served = servedValues(draft, projectName);
170	
171	  async function save() {
172	    if (saving || !dirty) return;
173	    setSaving(true);
174	    setSaveError(null);
175	    try {
176	      const res = await fetch(endpoint, {
177	        method: "PUT",
178	        headers: { "Content-Type": "application/json" },
179	        body: JSON.stringify({
180	          title: draft.title,
181	          description: draft.description,
182	          ogTitle: draft.ogTitle,
183	          ogDescription: draft.ogDescription,
184	        }),
185	      });
186	      if (res.status === 404 || res.status === 405) {
187	        setSaveSupport("missing");
188	        throw new Error("Saving isn't wired up on the server yet.");
189	      }
190	      const body = await res.json().catch(() => ({}));
191	      if (!res.ok) throw new Error(body?.error ?? "Couldn't save these.");
192	      setSavedAt(Date.now());
193	      await onSaved();
194	    } catch (err) {
195	      setSaveError(err instanceof Error ? err.message : "Couldn't save these.");
196	    } finally {
197	      setSaving(false);
198	    }
199	  }
200	
201	  const field = (
202	    key: "title" | "description" | "ogTitle" | "ogDescription",
203	    label: string,
204	    hint: string,
205	    target: number | null,
206	    multiline: boolean,
207	  ) => {
208	    const value = draft[key];
209	    const inputId = `kodely-seo-${key}`;
210	    const hintId = `${inputId}-hint`;
211	    const over = target !== null && value.length > target;
212	    return (
213	      <div>
214	        <div className="flex items-baseline justify-between gap-2">
215	          <label htmlFor={inputId} className="text-xs font-medium">
216	            {label}
217	          </label>
218	          {target !== null && (
219	            <span
220	              className={`shrink-0 text-xs tabular-nums ${
221	                over ? "text-amber-600 dark:text-amber-500" : "text-black/40 dark:text-white/40"
222	              }`}
223	            >
224	              {value.length}/{target}
225	            </span>
226	          )}
227	        </div>
228	        {multiline ? (
229	          <textarea
230	            id={inputId}
231	            value={value}
232	            rows={3}
233	            onChange={(e) => setDraft((d) => ({ ...d, [key]: e.target.value }))}
234	            aria-describedby={hintId}
235	            className={`mt-1 resize-none ${FIELD}`}
236	          />
237	        ) : (
238	          <input
239	            id={inputId}
240	            type="text"
241	            value={value}
242	            onChange={(e) => setDraft((d) => ({ ...d, [key]: e.target.value }))}
243	            aria-describedby={hintId}
244	            className={`mt-1 ${FIELD}`}
245	          />
246	        )}
247	        <p id={hintId} className="mt-1 text-xs text-black/40 dark:text-white/40">
248	          {hint}
249	          {target !== null && over && ` Over ~${target} characters, so search results will trim it.`}
250	        </p>
251	      </div>
252	    );
253	  };
254	
255	  return (
256	    <div className="h-full overflow-y-auto p-4">
257	      <div className="mx-auto max-w-2xl">
258	        <h2 className="text-sm font-medium">Search &amp; social</h2>
259	        <p className="mt-1 text-xs text-black/50 dark:text-white/50">
260	          The tab title, the search-result snippet and the link preview, read from your{" "}
261	          <code className="rounded bg-black/5 px-1 py-0.5 dark:bg-white/10">index.html</code>. Editing
262	          them here changes them directly — no build, no credits. A later build can rewrite them
263	          again, since the builder writes the head too.
264	        </p>
265	
266	        {html === undefined ? (
267	          <p className="mt-4 rounded-lg border border-black/10 px-3 py-2 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
268	            This project has no index.html yet, so there is nothing to edit.
269	          </p>
270	        ) : (
271	          <>
272	            <div className="mt-4 space-y-4">
273	              {field(
274	                "title",
275	                "Page title",
276	                "Shown in the browser tab and as the headline of a search result.",
277	                TITLE_TARGET,
278	                false,
279	              )}
280	              {field(
281	                "description",
282	                "Meta description",
283	                "The grey snippet under the headline in search results.",
284	                DESC_TARGET,
285	                true,
286	              )}
287	              {field(
288	                "ogTitle",
289	                "Share title (og:title)",
290	                "The bold line when someone pastes your link into a chat or a post.",
291	                TITLE_TARGET,
292	                false,
293	              )}
294	              {field(
295	                "ogDescription",
296	                "Share description (og:description)",
297	                "The smaller line under it. Left blank, it does NOT copy your meta description — a generic one is used instead.",
298	                DESC_TARGET,
299	                true,
300	              )}
301	            </div>
302	
303	            <div className="mt-3 flex flex-wrap items-center gap-2">
304	              <button
305	                type="button"
306	                onClick={save}
307	                disabled={!dirty || saving || saveSupport !== "ready"}
308	                className={`rounded-lg bg-black px-3 py-2 text-sm font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black ${FOCUS_RING}`}
309	              >
310	                {saving ? "Saving…" : "Save"}
311	              </button>
312	              <button
313	                type="button"
314	                onClick={() => setDraft(current)}
315	                disabled={!dirty || saving}
316	                className={`rounded-lg border border-black/15 px-3 py-2 text-sm disabled:opacity-40 dark:border-white/15 ${FOCUS_RING}`}
317	              >
318	                Reset
319	              </button>
320	              {/* One status region for this panel, and it never carries a
321	                  string that is announced anywhere else on the screen. */}
322	              <p role="status" className="text-xs text-black/50 dark:text-white/50">
323	                {saveError
324	                  ? ""
325	                  : savedAt !== null && !dirty
326	                    ? "Saved to your draft."
327	                    : dirty
328	                      ? "Unsaved changes."
329	                      : ""}
330	              </p>
331	            </div>
332	
333	            {saveError && <p className="mt-2 text-xs text-red-600">{saveError}</p>}
334	
335	            {saveSupport === "missing" && (
336	              // Deliberately concrete. "Saving is unavailable" tells a user
337	              // nothing; naming the missing route tells whoever has to fix it
338	              // exactly what is missing, and tells the user this is a gap in
339	              // Kodely rather than something they did wrong.
340	              <p className="mt-2 rounded-md border border-amber-500/40 px-2.5 py-2 text-xs text-amber-700 dark:text-amber-500">
341	                Saving isn&rsquo;t available yet — this build of Kodely has no{" "}
342	                <code>PUT {endpoint}</code> endpoint. You can still read and rehearse the values
343	                here; they will not persist.
344	              </p>
345	            )}
346	
347	            <h3 className="mt-6 text-xs font-medium">What a visitor sees</h3>
348	            <p className="mt-1 text-xs text-black/40 dark:text-white/40">
349	              Anything you leave blank is filled in on the published site by Kodely&rsquo;s backstop,
350	              so a site is never served with an empty head. These are the values it would use.
351	            </p>
352	            <dl className="mt-2 divide-y divide-black/10 rounded-lg border border-black/10 text-xs dark:divide-white/10 dark:border-white/10">
353	              <Served label="Title" value={served.title} fallback={served.titleIsFallback} />
354	              <Served
355	                label="Description"
356	                value={served.description}
357	                fallback={served.descriptionIsFallback}
358	              />
359	              <Served label="og:title" value={served.ogTitle} fallback={served.ogTitleIsFallback} />
360	              <Served
361	                label="og:description"
362	                value={served.ogDescription}
363	                fallback={served.ogDescriptionIsFallback}
364	              />
365	              {current.ogImage && <Served label="og:image" value={current.ogImage} fallback={false} />}
366	            </dl>
367	
368	            <h3 className="mt-6 text-xs font-medium">Handled for you</h3>
369	            <ul className="mt-2 space-y-1 text-xs text-black/50 dark:text-white/50">
370	              <li>
371	                <code>canonical</code> and <code>og:url</code> — set to{" "}
372	                {liveUrl ? <span className="break-all">{liveUrl}</span> : "your site's address"} when
373	                a page is served.
374	              </li>
375	              <li>
376	                <code>og:type</code> and <code>twitter:card</code> — filled in if the page has none.
377	              </li>
378	              <li>
379	                <code>og:image</code> — a relative path is rewritten to a full URL, because crawlers
380	                reject relative ones.
381	              </li>
382	              <li>
383	                <code>robots.txt</code> and <code>sitemap.xml</code> — generated for every published
384	                site from its own pages.
385	              </li>
386	            </ul>
387	
388	            <p className="mt-4 text-xs text-black/40 dark:text-white/40">
389	              {published
390	                ? "Saving updates your draft and the preview. Your live site keeps its current tags until you republish."
391	                : "Saving updates your draft. These go live the first time you publish."}
392	            </p>
393	          </>
394	        )}
395	      </div>
396	    </div>
397	  );
398	}
399	
400	function Served({
401	  label,
402	  value,
403	  fallback,
404	}: {
405	  label: string;
406	  value: string;
407	  fallback: boolean;
408	}) {
409	  return (
410	    <div className="flex flex-col gap-0.5 px-3 py-2 sm:flex-row sm:gap-3">
411	      <dt className="shrink-0 text-black/40 sm:w-28 dark:text-white/40">{label}</dt>
412	      <dd className="min-w-0 break-words">
413	        {value}
414	        {fallback && (
415	          <span className="ml-1.5 whitespace-nowrap rounded border border-black/10 px-1 py-0.5 text-[10px] text-black/40 dark:border-white/10 dark:text-white/40">
416	            filled in for you
417	          </span>
418	        )}
419	      </dd>
420	    </div>
421	  );
422	}
